            FB_Shipment_Event__e evt = new FB_Shipment_Event__e();
            evt.Order_Number__c = s.orderNumber;
            evt.Tracking_Number__c = s.trackingNumber;
            evt.Carrier__c = s.carrier;
            events.add(evt);
        }

        if (events.isEmpty()) {
            return 0;
        }

        List<Bus.PublishResult> results = Bus.publish(events);
        Integer publishedCount = 0;
        for (Bus.PublishResult r : results) {
            if (r.isSuccess()) {
                publishedCount++;
            }
        }
        return publishedCount;
    }
