public class Opportunities extends fflib_SObjectDomain {

    private final Set<Id> qualifyingOpportunityIds = new Set<Id>();

    public class Constructor implements fflib_SObjectDomain.IConstructable {

        private final String event;
        private final Map<Id, SObject> sObjectMap;
        private final Map<Id, SObject> oldSObjectMap;

        public Constructor(
            List<SObject> newRecords,
            List<SObject> oldRecords,
            Boolean isInsert,
            Boolean isUpdate,
            Boolean isDelete,
            Boolean isAfter
        ) {
            this.sObjectMap = fflib_SObjectUtils.sObjectListToMap(newRecords);
            this.oldSObjectMap = fflib_SObjectUtils.sObjectListToMap(oldRecords);

            if (isAfter) {
                if (isInsert) {
                    this.event = 'afterInsert';
                } else if (isUpdate) {
                    this.event = 'afterUpdate';
                } else if (isDelete) {
                    this.event = 'afterDelete';
                } else {
                    this.event = 'afterUndelete';
                }
            } else {
                if (isInsert) {
                    this.event = 'beforeInsert';
                } else if (isUpdate) {
                    this.event = 'beforeUpdate';
                } else if (isDelete) {
                    this.event = 'beforeDelete';
                } else {
                    this.event = 'beforeUndelete';
                }
            }
        }

        public String getEvent() {
            return this.event;
        }

        public Map<Id, SObject> getSObjectMap() {
            return this.sObjectMap;
        }

        public Map<Id, SObject> getOldSObjectMap() {
            return this.oldSObjectMap;
        }
    }

    public Opportunities(fflib_SObjectDomain.IConstructable c) : super(c) {}

    public override void afterInsert() {
        for (Id id : this.sObjectMap.keySet()) {
            Opportunity opp = (Opportunity) this.sObjectMap.get(id);
            if (opp.StageName == 'Closed Won') {
                this.qualifyingOpportunityIds.add(id);
            }
        }
        this.commitFulfilment();
    }

    public override void afterUpdate() {
        for (Id id : this.sObjectMap.keySet()) {
            Opportunity opp = (Opportunity) this.sObjectMap.get(id);
            Opportunity oldOpp = (Opportunity) this.oldSObjectMap.get(id);
            if (opp.StageName == 'Closed Won' && oldOpp.StageName != 'Closed Won') {
                this.qualifyingOpportunityIds.add(id);
            }
        }
        this.commitFulfilment();
    }

    private void commitFulfilment() {
        if (!this.qualifyingOpportunityIds.isEmpty()) {
            IOpportunityFulfilmentService service =
                Application.Service.newInstance(IOpportunityFulfilmentService.class);
            service.startFulfilment(this.qualifyingOpportunityIds);
        }
    }
}
