import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

const REFRESH_INTERVAL_MS = 60000;

export default class QueueMonitor extends LightningElement {
    waiting = null;
    longestWaitMinutes = null;
    error = null;
    loaded = false;

    _isRequestInFlight = false;
    _intervalId = null;
    _boundVisibilityHandler = null;

    connectedCallback() {
        this.loadStats();
        this._intervalId = setInterval(() => this.loadStats(), REFRESH_INTERVAL_MS);
        this._boundVisibilityHandler = () => this._onVisibilityChange();
        document.addEventListener('visibilitychange', this._boundVisibilityHandler);
    }

    disconnectedCallback() {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
        if (this._boundVisibilityHandler !== null) {
            document.removeEventListener('visibilitychange', this._boundVisibilityHandler);
            this._boundVisibilityHandler = null;
        }
        this._isRequestInFlight = false;
    }

    async loadStats() {
        if (this._isRequestInFlight) return;
        if (document.visibilityState === 'hidden') return;

        this._isRequestInFlight = true;
        try {
            const stats = await getQueueStats();
            this.waiting = stats.waiting;
            this.longestWaitMinutes = stats.longestWaitMinutes;
            this.loaded = true;
            this.error = null;
        } catch (err) {
            this.error = err.body.message;
        } finally {
            this._isRequestInFlight = false;
        }
    }

    _onVisibilityChange() {
        if (document.visibilityState === 'visible') {
            this.loadStats();
        }
    }
}
